# Make the unified engine importable. `import memory` must resolve to the store
# engine (MEM20_STORE_PATH, default ~/.mem20/store), the engine every handler's API
# contract is written against. The repo-root shim (memory_engine/memory.py) shares
# this module; code and data are fully separated. The store path MUST be nearer the
# front of sys.path than _REPO_ROOT so `import memory` finds ~/.mem20/store/memory.py
# and not the legacy standalone engine at /opt/mem20/memory.py (which would be
# cached in sys.modules and poison recall, pinned-block, and ledger tools alike).
_REPO_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
_MEMORY_ENGINE_DIR = os.path.expanduser(os.environ.get("MEM20_STORE_PATH", os.path.join(os.path.expanduser("~"), ".mem20", "store")))
# Store path must be first so `import memory` resolves to the store engine, not the legacy repo-root shim.
for _p in (_MEMORY_ENGINE_DIR, _REPO_ROOT):
    while _p in sys.path:
        sys.path.remove(_p)
sys.path.insert(0, _MEMORY_ENGINE_DIR)
# Append repo root (not insert at front) to avoid shadowing installed packages (e.g. mem20langz venv install).
sys.path.append(_REPO_ROOT)
_memory_state = {"loaded": False, "available": False, "audit": None}


def _load_memory_api():
    if _memory_state["loaded"]:
        return
    _memory_state["loaded"] = True
    try:
        import memory as _memory  # noqa: F401
        _memory_state["available"] = True
        _memory_state["audit"] = getattr(_memory, "audit_contamination", None)
    except Exception:
        _memory_state["available"] = False
        _memory_state["audit"] = None


def memory_system_available():
    _load_memory_api()
    return bool(_memory_state["available"])


def engine_audit():
    _load_memory_api()
    return _memory_state["audit"]


